-- Selective, reviewed publishing of owner-private experience records. No automatic synchronization.
begin;
create table if not exists public.cb_experience_imports(user_id uuid not null references auth.users on delete cascade,scope text not null check(scope in ('personal','demo')),project_ref text not null,record_ref text not null,event_id uuid not null references public.cb_project_events on delete cascade,item_id uuid not null unique references public.cb_experience_items on delete cascade,source_hash text not null,created_at timestamptz not null default now(),primary key(user_id,scope,project_ref,record_ref,event_id));
create table if not exists public.cb_experience_import_writes(user_id uuid not null references auth.users on delete cascade,client uuid not null,payload jsonb not null,response jsonb not null,primary key(user_id,client));
alter table public.cb_experience_imports enable row level security;alter table public.cb_experience_import_writes enable row level security;revoke all on public.cb_experience_imports,public.cb_experience_import_writes from public,anon,authenticated;
create or replace function public.cb_experience_personal_source(p_scope text,p_project text,p_ref text) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare p jsonb;r jsonb;pid uuid;begin
 if auth.uid() is null or p_scope is null or p_scope not in ('personal','demo') or length(coalesce(p_project,'')) not between 1 and 200 or length(coalesce(p_ref,'')) not between 1 and 200 then raise exception 'Open your own saved experience plan' using errcode='42501';end if;
 select body->'value' into p from public.cb_workspace_records where user_id=auth.uid() and workspace='bride' and to_revision is null and body->>'kind'='item' and body->'value'->>'id'=p_project and (body->'path'=jsonb_build_array(p_scope,'projects') or p_scope='personal' and body->'path'=jsonb_build_array('projects')) order by jsonb_array_length(body->'path') desc limit 1;
 select body->'value' into r from public.cb_workspace_records where user_id=auth.uid() and workspace='bride' and to_revision is null and body->>'kind'='item' and body->'value'->>'id'=p_ref and (body->'path'=jsonb_build_array(p_scope,'experienceRecords') or p_scope='personal' and body->'path'=jsonb_build_array('experienceRecords')) order by jsonb_array_length(body->'path') desc limit 1;
 if p is null or r is null or r->>'projectId' is distinct from p_project or coalesce(p->>'archived','false')='true' or coalesce(p->>'archiveStatus','') like 'Archived%' or coalesce(r->>'archived','false')='true' then raise exception 'Open your own active experience record first' using errcode='42501';end if;
 if coalesce(p->>'sharedProjectId','')!~'^[a-fA-F0-9-]{36}$' then raise exception 'Connect this wedding to its team workspace first';end if;pid=(p->>'sharedProjectId')::uuid;
 if not coalesce(public.cb_project_access(pid,'write'),false) then raise exception 'Planning access is required to share this record' using errcode='42501';end if;
 return jsonb_build_object('project',pid,'hash',md5(r::text),'cancelled',r->>'status'='Cancelled','data',jsonb_build_object('title',coalesce(r->>'title',''),'section',coalesce(r->>'section',''),'status','Planned','brief','','specifications',coalesce(r->>'details',''),'supplier','','quantity',coalesce(r->'quantity','0'::jsonb),'unit',case when r->>'section' in ('food','cake') then 'portions' when r->>'section'='drinks' then 'servings / units' else 'planned units' end,'time',coalesce(r->>'time',''),'order',0,'url',coalesce(r->>'url',''),'checks','[]'::jsonb));end;$$;
create or replace function public.cb_experience_share_preview(p_scope text,p_project text,p_ref text) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare src jsonb;pid uuid;begin
 src=public.cb_experience_personal_source(p_scope,p_project,p_ref);pid=(src->>'project')::uuid;
 return src||jsonb_build_object('events',(select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'title',e.title,'revision',e.revision,'date',e.details->>'date') order by e.details->>'date',e.title,e.id),'[]') from public.cb_project_events e where e.project_id=pid and public.cb_experience_member(e.id,auth.uid())),'shared',(select coalesce(jsonb_agg(jsonb_build_object('event',l.event_id,'item',l.item_id,'source_changed',l.source_hash is distinct from src->>'hash')),'[]') from public.cb_experience_imports l where l.user_id=auth.uid() and l.scope=p_scope and l.project_ref=p_project and l.record_ref=p_ref and exists(select 1 from public.cb_project_events e where e.id=l.event_id and e.project_id=pid and public.cb_experience_member(e.id,auth.uid()))));end;$$;
create or replace function public.cb_share_experience_record(p_scope text,p_project text,p_ref text,p_event uuid,p_event_revision bigint,p_source_hash text,p_client uuid,p_data jsonb,p_confirm boolean) returns jsonb language plpgsql security definer set search_path='' as $$
declare ev public.cb_project_events;src jsonb;prior public.cb_experience_import_writes;l public.cb_experience_imports;payload jsonb;item jsonb;result jsonb;begin
 select * into ev from public.cb_project_events where id=p_event;perform 1 from public.cb_projects where id=ev.project_id for update;perform 1 from public.cb_workspace_states where user_id=auth.uid() and workspace='bride' for update;
 src=public.cb_experience_personal_source(p_scope,p_project,p_ref);select * into ev from public.cb_project_events where id=p_event for update;
 if ev.id is null or ev.project_id::text is distinct from src->>'project' or not coalesce(public.cb_experience_member(ev.id,auth.uid()),false) then raise exception 'Choose an accessible celebration in this wedding' using errcode='42501';end if;
 payload=jsonb_build_object('scope',p_scope,'project',p_project,'ref',p_ref,'event',p_event,'event_revision',p_event_revision,'hash',p_source_hash,'data',p_data,'confirm',p_confirm);
 if p_client is null then raise exception 'Request ID required';end if;select * into prior from public.cb_experience_import_writes where user_id=auth.uid() and client=p_client;if found then if prior.payload is distinct from payload then raise exception 'Retry the same reviewed service plan' using errcode='PT409';end if;return prior.response;end if;
 if p_confirm is distinct from true then raise exception 'Review the service fields and confirm sharing';end if;
 if ev.revision is distinct from p_event_revision or src->>'hash' is distinct from p_source_hash then raise exception 'The source plan or destination changed. Refresh the preview before sharing.' using errcode='PT409';end if;
 select * into l from public.cb_experience_imports where user_id=auth.uid() and scope=p_scope and project_ref=p_project and record_ref=p_ref and event_id=p_event;
 if found then result=jsonb_build_object('item',l.item_id,'event',ev.id,'already_shared',true);else
 if coalesce((src->>'cancelled')::boolean,false) then raise exception 'Reopen the cancelled personal service before sharing it';end if;
 if p_data->>'status' is distinct from 'Planned' or p_data->>'brief' is distinct from '' or p_data->>'supplier' is distinct from '' or p_data->'checks' is distinct from '[]'::jsonb then raise exception 'Shared imports start as planned with separate readiness and professional assignments';end if;
 item=public.cb_save_experience_item(ev.id,ev.revision,null,0,gen_random_uuid(),p_data,null);
 insert into public.cb_experience_imports(user_id,scope,project_ref,record_ref,event_id,item_id,source_hash) values(auth.uid(),p_scope,p_project,p_ref,ev.id,(item->>'id')::uuid,src->>'hash');result=jsonb_build_object('item',item->>'id','event',ev.id,'already_shared',false);
 end if;
 insert into public.cb_experience_import_writes values(auth.uid(),p_client,payload,result);return result;
end;$$;
revoke all on function public.cb_experience_personal_source(text,text,text),public.cb_experience_share_preview(text,text,text),public.cb_share_experience_record(text,text,text,uuid,bigint,text,uuid,jsonb,boolean) from public,anon,authenticated;
grant execute on function public.cb_experience_share_preview(text,text,text),public.cb_share_experience_record(text,text,text,uuid,bigint,text,uuid,jsonb,boolean) to authenticated;
notify pgrst,'reload schema';commit;
